const developer = {
​  nombre: " Sebastian Mesa",
​  rol: "Full Stack Developer",
​  ubicacion: "Medellín, Colombia",
​  
​  habilidades: [
​    "React", "JavaScript", "TailwindCSS",
​    "Node.js", "MongoDB", "Git"
​  ],
​  
​  pasiones: [
​    "Crear interfaces hermosas",
​    "Resolver problemas complejos",
​    "Aprender nuevas tecnologías"
​  ],
​  
​  getCafe: function() {
​    return "☕ Siempre listo para programar";
​  }
};

console.log(developer.getCafe());
// Output: ☕ Siempre listo para programar`},"proyectos/ecommerce.jsx":{language:"jsx",content:`// 🛒 E-Commerce Platform
import React from 'react';

const EcommercePlatform = () => {
​  const proyecto = {
​    nombre: "ShopHub",
​    descripcion: "Plataforma de comercio electrónico completa",
​    tecnologias: ["React", "Node.js", "Stripe", "MongoDB"],
​    caracteristicas: [
​      "Carrito de compras en tiempo real",
​      "Pasarela de pagos integrada",
​      "Panel de administración",
​      "Sistema de reviews"
​    ],
​    estado: "Producción ✅"
​  };

​  return (
​    <div className="proyecto">
​      <h2>{proyecto.nombre}</h2>
​      <p>{proyecto.descripcion}</p>
​    </div>
​  );
};

export default EcommercePlatform;`},"proyectos/portfolio.tsx":{language:"typescript",content:`// 🎨 Portfolio Personal
